/* @lc app=leetcode id=2973 lang=kotlin */
class Solution { fun placedCoins(edges: Array<IntArray>, cost: IntArray): LongArray = Array(cost.size) { mutableListOf<Int>() }.also { adj -> edges.forEach { e -> adj[e[0]].add(e[1]).also { adj[e[1]].add(e[0]) } } }.let { adj -> LongArray(cost.size).let { ans -> DeepRecursiveFunction<Pair<Int, Int>, List<Long>> { pair -> pair.first.let { u -> pair.second.let { p -> adj[u].filter { it != p }.flatMap { v -> callRecursive(v to u) }.plus(cost[u].toLong()).sorted().let { list -> list.also { if (it.size < 3) ans[u] = 1L else ans[u] = maxOf(0L, it.last() * it[it.size - 2] * it[it.size - 3], it[0] * it[1] * it.last()) }.let { if (it.size <= 5) it else listOf(it[0], it[1], it[it.size - 3], it[it.size - 2], it.last()) } } } } }.callRecursive(0 to -1).let { ans } } }